        private static bool IsOutlaw(Faction faction)
        {
            string name=((faction?.def?.defName??"")+" "+
                (faction?.def?.label??"")).ToLowerInvariant();
            return Has(name,"pirate","raider","bandit","outlaw","rough",
                "пират","рейдер","бандит","налётчик");
        }
        public static string Office(Pawn pawn, int rank)
        {
            int r = Math.Max(0,Math.Min(8,rank));
            TechLevel tech=pawn?.Faction?.def?.techLevel??TechLevel.Neolithic;
            string[][] catalog=IsOutlaw(pawn?.Faction) ? Outlaw :
                tech<TechLevel.Medieval ? Clan :
                tech<TechLevel.Industrial ? Traditional : Industrial;
            string[] offices=catalog[r];
            int seed=(pawn?.thingIDNumber ?? 17) & int.MaxValue;
            return offices[(seed+r*7)%offices.Length];
        }

        // Role-specific actual consequences; the rank controls the territorial
        // scope, the office controls WHAT the pawn is responsible for.
        public static string Responsibility(string office, int rank)
        {
            string n = (office ?? "").ToLowerInvariant();
            string duty;
            if (Has(n,"наук","исслед","лаборатор","архив","академ","инженер","ремесл"))
                duty = "Отвечает за знания, испытания, подготовку специалистов и сохранение результатов исследований. Его потеря задерживает проекты и уменьшает круг доступных экспертов.";
            else if (Has(n,"арм","воен","команд","штаб","развед","страж","дозор","гарниз","воевод","дружин","адмирал","маршал"))
                duty = "Руководит людьми и военной подготовкой, получает донесения, распределяет вооружение или планирует операции. Его отсутствие бьёт по боеспособности и доверию подчинённых.";
            else if (Has(n,"снабж","склад","транспорт","порт","караван","торгов","финанс","казн","продоволь","ресурс"))
                duty = "Управляет поставками, расчётами и хозяйственными договорами. Его пленение разрывает маршруты, срывает сделки и затрагивает торговых партнёров.";
            else if (Has(n,"жрец","шаман","друид","храм","свят","вер","церк"))
                duty = "Сохраняет духовные традиции, ведёт обряды и обладает влиянием среди верующих. Угроза такому лицу может вызвать общественное и религиозное давление.";
            else if (Has(n,"врач","леч","больниц","медиц","знах","травник"))
                duty = "Отвечает за лечение людей и медицинские знания. Его похищение ставит под угрозу пациентов и заставляет коллег искать способы вернуть специалиста.";
            else if (Has(n,"суд","совет","префект","министр","намест","губерн","канцлер","правит","архонт","глава","старейшин","магистрат","консул"))
                duty = "Принимает решения по управлению людьми и разрешению споров. Исчезновение нарушает цепочку полномочий и провоцирует борьбу за временное руководство.";
            else
                duty = "Имеет устойчивые связи с сослуживцами, соседями или представителями своей профессии. Его потеря сильнее всего затрагивает тех, кто зависит от его работы.";
            string scale=rank>=7 ? "Масштаб: несколько крупных областей или вся фракция." :
                rank>=6 ? "Масштаб: регион и несколько поселений." :
                rank>=5 ? "Масштаб: крупное поселение или округ." :
                rank>=3 ? "Масштаб: местная община, учреждение или подразделение." :
                "Масштаб: личные и ближайшие социальные связи.";
            return duty + "\n" + scale;
        }
        private static bool Has(string n,params string[] parts)
        {
            for(int i=0;i<parts.Length;i++)if(n.Contains(parts[i]))return true;
            return false;
        }
